CREATE OR REPLACE PROCEDURE sp(
    arg1 integer,
    arg2 text,
    arg3 integer,
    arg4 integer,
    arg5 text,
    arg6 integer
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_weight_increment integer := 1;
    p_cutoffs integer[];
    t_cutoffs integer[];
    pbmarkers text[];
    tsmarkers text[];
    v_phase integer;
BEGIN
    pbmarkers := ARRAY['phase_1','phase_2','phase_3','phase_4','phase_5','phase_6','phase_7','phase_8','phase_9'];
    tsmarkers := ARRAY['log_phase_1','log_phase_2','log_phase_3','log_phase_4','log_phase_5','log_phase_6','log_phase_7','log_phase_8','log_phase_9'];
    p_cutoffs := ARRAY[arg3 + 0, arg3 + 1, arg3 + 10, arg3 + 3, arg3 + 4, arg3 + 5, arg3 + 6, arg3 + 7, arg3 + 8];
    t_cutoffs := ARRAY[arg6 + 0, arg6 + 1, arg6 + 2, arg6 + 3, arg6 + 4, arg6 + 5, arg6 + 6, arg6 + 7, arg6 + 8];

    FOR v_phase IN 1..9 LOOP
        UPDATE "Player" SET birthday = pbmarkers[v_phase];
        DELETE FROM "Player" WHERE player_api_id < p_cutoffs[v_phase];
        UPDATE "Team" SET team_short_name = tsmarkers[v_phase];
        DELETE FROM "Team" WHERE team_fifa_api_id < t_cutoffs[v_phase];
    END LOOP;

    UPDATE "Player" SET weight = weight + v_weight_increment WHERE height < arg1;

    IF arg5 IS NOT NULL THEN
        UPDATE "Team" SET team_long_name = arg5 WHERE team_short_name = 'log_phase_9' AND team_api_id >= arg4;
    END IF;

    UPDATE "Player_Attributes" SET potential = overall_rating WHERE player_api_id >= arg3 AND potential < overall_rating;

    UPDATE "Team_Attributes" ta SET defenceAggression = ta.defencePressure WHERE ta.defenceAggression < ta.defencePressure AND EXISTS (SELECT 1 FROM "Team" t WHERE t.team_api_id = ta.team_api_id AND t.team_fifa_api_id >= arg6);
END;
$$;

